// Prepare email data for classification
const input = $input.first().json;

// n8n Webhook may nest POST body under input.body or place it directly on input
const data = input.body || input;
const email = data.email;

if (!email) {
  throw new Error('No email found in webhook payload. Keys received: ' + Object.keys(input).join(', ') + (input.body ? ' | body keys: ' + Object.keys(input.body).join(', ') : ''));
}

// Build attachment summaries (without base64 content for LLM)
const attachments = email.attachments || [];
const attachmentSummaries = attachments.map(att => ({
  file_name: att.file_name || 'unknown',
  file_extension: att.file_extension || '',
  file_category: att.file_category || 'other',
  file_size_formatted: att.file_size_formatted || 'unknown'
}));

// Build classification prompt
const classificationPrompt = `You are an insurance email classification and data extraction expert.

Analyze the following email and its attachments, then:
1. Classify the email into one of these categories: Quote, BOR (Broker of Record), Cancellation, Endorsement, Renewal, Claim, General Inquiry, Other
2. Extract the following key details (return null if not found):
   - Policy Number
   - Customer ID
   - Quote Number
   - Attachment Type (e.g., BOR Letter, Cancellation Form, Insurance Application, etc.)
   - Email Subject
   - Email Body Summary (2-3 sentences)
   - Insured Name
   - Effective Date
   - Vehicle Info (if applicable)

EMAIL DETAILS:
From: ${email.from_name} <${email.from_email}>
To: ${email.to_name} <${email.to_email}>
Subject: ${email.subject}
Date: ${email.received_at}

EMAIL BODY:
${email.body_plain}

ATTACHMENTS:
${attachmentSummaries.map(a => '- ' + a.file_name + ' (' + a.file_category + ', ' + a.file_size_formatted + ')').join('\n')}

Respond in this exact JSON format (no markdown, no code blocks, just raw JSON):
{
  "category": "<category>",
  "confidence": <0.0-1.0>,
  "policy_number": "<value or null>",
  "customer_id": "<value or null>",
  "quote_number": "<value or null>",
  "attachment_type": "<value or null>",
  "email_subject": "<value>",
  "email_body_summary": "<value>",
  "insured_name": "<value or null>",
  "effective_date": "<value or null>",
  "vehicle_info": "<value or null>"
}`;

return [{
  json: {
    event: data.event,
    email_index: data.email_index,
    total_emails: data.total_emails,
    email,
    classificationPrompt,
    attachmentSummaries
  }
}];

// Parse classification result and prepare response generation prompt
const input = $input.first().json;

// Get the previous items data from Prepare Classification node
let allData;
try {
  allData = $('Prepare Classification').first().json;
} catch(e) {
  allData = input;
}
const email = allData.email || {};
const attachmentSummaries = allData.attachmentSummaries || [];

// Parse Azure OpenAI response
let classification = {};
try {
  // input may have choices directly or nested under body
  const choices = input.choices || (input.body && input.body.choices);
  const content = choices[0].message.content;
  // Try to parse JSON - handle potential markdown code blocks
  let jsonStr = content;
  if (content.includes('```')) {
    jsonStr = content.replace(/```json?\n?/g, '').replace(/```/g, '').trim();
  }
  classification = JSON.parse(jsonStr);
} catch(e) {
  classification = {
    category: 'Unknown',
    confidence: 0,
    policy_number: null,
    customer_id: null,
    quote_number: null,
    attachment_type: null,
    email_subject: email.subject || 'Unknown',
    email_body_summary: 'Unable to parse classification: ' + e.message,
    insured_name: null,
    effective_date: null,
    vehicle_info: null
  };
}

const confPct = classification.confidence ? (classification.confidence * 100).toFixed(0) : '0';

// Build response generation prompt
const responsePrompt = `You are a professional insurance operations assistant at Wonderland Global Insurance.

Based on the email classification and extracted details below, generate a professional response email.

EMAIL CLASSIFICATION:
- Category: ${classification.category}
- Confidence: ${confPct}%

EXTRACTED DETAILS:
- Policy Number: ${classification.policy_number || 'Not found'}
- Customer ID: ${classification.customer_id || 'Not found'}
- Quote Number: ${classification.quote_number || 'Not found'}
- Attachment Type: ${classification.attachment_type || 'Not found'}
- Insured Name: ${classification.insured_name || 'Not found'}
- Effective Date: ${classification.effective_date || 'Not found'}
- Vehicle Info: ${classification.vehicle_info || 'Not applicable'}

ORIGINAL EMAIL:
From: ${email.from_name || 'Unknown'} <${email.from_email || ''}>
Subject: ${email.subject || 'No subject'}
Body Summary: ${classification.email_body_summary || ''}

ATTACHMENTS RECEIVED:
${attachmentSummaries.map(a => '- ' + a.file_name + ' (' + a.file_category + ')').join('\n')}

Generate a professional response that:
1. Acknowledges receipt of the email and attachments
2. Confirms the identified category (${classification.category})
3. Lists the extracted details found
4. Mentions any details that could not be found and may need clarification
5. Provides appropriate next steps based on the category
6. Is signed by "Wonderland Team, Email Processing Division"

Respond with ONLY the email body text (no subject line, no JSON, just the response text).`;

return [{
  json: {
    email,
    classification,
    responsePrompt,
    attachmentSummaries
  }
}];

// Build the final webhook response
const llmResponse = $input.first().json;

// Get data from Parse & Prepare Response node
let prevData;
try {
  prevData = $('Parse & Prepare Response').first().json;
} catch(e) {
  prevData = {};
}
const email = prevData.email || {};
const classification = prevData.classification || {};
const attachmentSummaries = prevData.attachmentSummaries || [];

// Extract the generated response text
let responseBody = 'Thank you for your email. We are reviewing your request and will respond shortly.';
try {
  const choices = llmResponse.choices || (llmResponse.body && llmResponse.body.choices);
  responseBody = choices[0].message.content;
} catch(e) {
  // fallback already set
}

// Build the final response payload
return [{
  json: {
    success: true,
    email_id: email.id || null,
    email_subject: email.subject || 'Unknown',
    classification: {
      category: classification.category || 'Unknown',
      confidence: classification.confidence || 0
    },
    extracted_details: {
      policy_number: classification.policy_number || null,
      customer_id: classification.customer_id || null,
      quote_number: classification.quote_number || null,
      attachment_type: classification.attachment_type || null,
      insured_name: classification.insured_name || null,
      effective_date: classification.effective_date || null,
      vehicle_info: classification.vehicle_info || null,
      email_subject: classification.email_subject || null,
      email_body_summary: classification.email_body_summary || null
    },
    response: {
      from_name: 'Wonderland Team',
      from_email: 'Emailprocessing@wonderlandglobal.com',
      to_name: email.from_name || '',
      to_email: email.from_email || '',
      subject: 'RE: ' + (email.subject || ''),
      body: responseBody,
      sent_at: new Date().toISOString()
    },
    attachments_processed: attachmentSummaries.map(a => a.file_name),
    processed_at: new Date().toISOString()
  }
}];
